+                       dim = GET_OP2_ZVAL_PTR_UNDEF(BP_VAR_R);
+                       if (OP2_TYPE == IS_CV && UNEXPECTED(Z_ISUNDEF_P(dim))) {
+                               zend_object *obj = Z_OBJ_P(container);
